def binary_search(arr: list[int], target: int) -> int:
    """Perform binary search on a sorted integer array.

    Returns the 0-based index of target if found, else -1.
    """
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def dfs(graph: dict[str, list[str]], start_node: str, visited: set[str] | None = None) -> list[str]:
    """Traverse an unweighted graph using depth-first search (DFS).

    Returns a list of visited nodes in order of discovery.
    """
    if visited is None:
        visited = set()
    traversal = [start_node]
    visited.add(start_node)
    for neighbor in graph.get(start_node, []):
        if neighbor not in visited:
            traversal.extend(dfs(graph, neighbor, visited))
    return traversal

from collections import deque

def bfs(graph: dict[str, list[str]], start_node: str) -> list[str]:
    """Traverse a graph level by level using breadth-first search (BFS).

    Returns a list of visited node identifiers.
    """
    visited = {start_node}
    queue = deque([start_node])
    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return order

import heapq

def dijkstra(graph: dict[str, list[tuple[str, float]]], start: str) -> dict[str, float]:
    """Compute shortest path distances from start node to all reachable nodes.

    Graph format: {node: [(neighbor, weight), ...]}
    """
    distances = {node: float('inf') for node in graph}
    distances[start] = 0.0
    pq = [(0.0, start)]

    while pq:
        cur_dist, u = heapq.heappop(pq)
        if cur_dist > distances[u]:
            continue
        for v, weight in graph.get(u, []):
            dist = cur_dist + weight
            if dist < distances[v]:
                distances[v] = dist
                heapq.heappush(pq, (dist, v))
    return distances

class LRUCache:
    """Least Recently Used (LRU) Cache with O(1) get and put operations."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache: dict[int, int] = {}

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        val = self.cache.pop(key)
        self.cache[key] = val
        return val

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.cache.pop(key)
        elif len(self.cache) >= self.capacity:
            oldest = next(iter(self.cache))
            del self.cache[oldest]
        self.cache[key] = value

class TrieNode:
    def __init__(self):
        self.children: dict[str, TrieNode] = {}
        self.is_end_of_word = False

class Trie:
    """Trie data structure for fast string insertion and prefix search."""
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def search(self, word: str) -> bool:
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end_of_word

def two_sum(nums: list[int], target: int) -> list[int]:
    """Find indices of the two numbers in nums that add up to target.

    O(n) time complexity using a dictionary complement lookup.
    """
    seen: dict[int, int] = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [seen[complement], i]
        seen[num] = i
    return []

def levenshtein_distance(s1: str, s2: str) -> int:
    """Compute the minimum edit distance (insertions, deletions, substitutions).

    Dynamic programming algorithm in O(m * n) time.
    """
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if s1[i - 1] == s2[j - 1] else 1
            dp[i][j] = min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost)
    return dp[m][n]

def is_valid_parentheses(s: str) -> bool:
    """Determine if the input string has valid matching brackets '()[]{}'.

    Utilizes a stack data structure for LIFO validation.
    """
    mapping = {')': '(', '}': '{', ']': '['}
    stack = []
    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
    return len(stack) == 0

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def inorder_traversal(root: TreeNode | None) -> list[int]:
    """Return the inorder traversal (Left -> Node -> Right) of a binary tree."""
    result = []
    def traverse(node):
        if node:
            traverse(node.left)
            result.append(node.val)
            traverse(node.right)
    traverse(root)
    return result

def fibonacci_memo(n: int, memo: dict[int, int] | None = None) -> int:
    """Compute the n-th Fibonacci number in O(n) time using top-down memoization."""
    if memo is None:
        memo = {0: 0, 1: 1}
    if n in memo:
        return memo[n]
    memo[n] = fibonacci_memo(n - 1, memo) + fibonacci_memo(n - 2, memo)
    return memo[n]
